// Generated by tools/sim/harness.py.
// One rising edge per cycle; inputs applied while the clock is low
// and outputs sampled before the edge, which is the cycle model
// tools/stage6_invert.py unrolls.

`timescale 1ns / 1ps

module tb_harness;
  reg clk = 1'b0;
  reg [0:0] A;
  reg [0:0] B;
  reg [0:0] en;
  reg [0:0] rst_n;
  wire [0:0] S;

  adder_demo dut (.A(A), .B(B), .S(S), .clk(clk), .en(en), .rst_n(rst_n));

  initial begin
    A = 1'd1;
    B = 1'd1;
    en = 1'd1;
    rst_n = 1'd1;
    #4;
    $display("SAMPLE %0d S=%b", 0, S);
    #1 clk = 1'b1;
    #4;
    #1 clk = 1'b0;
    A = 1'd1;
    B = 1'd1;
    en = 1'd1;
    rst_n = 1'd1;
    #4;
    $display("SAMPLE %0d S=%b", 1, S);
    #1 clk = 1'b1;
    #4;
    #1 clk = 1'b0;
    A = 1'd1;
    B = 1'd1;
    en = 1'd1;
    rst_n = 1'd1;
    #4;
    $display("SAMPLE %0d S=%b", 2, S);
