    #4;
    #1 clk = 1'b0;
    A = 1'd1;
    B = 1'd1;
    en = 1'd1;
    rst_n = 1'd1;
    #4;
    $display("SAMPLE %0d S=%b", 3, S);
    #1 clk = 1'b1;
    #4;
    #1 clk = 1'b0;
    A = 1'd1;
    B = 1'd0;
    en = 1'd1;
    rst_n = 1'd1;
    #4;
    $display("SAMPLE %0d S=%b", 4, S);
    #1 clk = 1'b1;
    #4;
    #1 clk = 1'b0;
    A = 1'd1;
    B = 1'd1;
    en = 1'd1;
    rst_n = 1'd1;
    #4;
    $display("SAMPLE %0d S=%b", 5, S);
    #1 clk = 1'b1;
    #4;
    #1 clk = 1'b0;
    A = 1'd0;
    B = 1'd0;
